// Pure helpers are exercised directly by Node without a desktop runtime.
const monthAfter = (m, n) => {
  const [year, month] = m.split('-').map(Number)
  const day = new Date(Date.UTC(year, month - 1 + n, 1))
  if (!Number.isFinite(day.getTime()) || day.getUTCFullYear() < 1 || day.getUTCFullYear() > 9999) throw Error("Forecast dates exceed the supported calendar.")
  return day.toISOString().slice(0, 7)
}
export const label = month => month
  ? new Date(`${month}-02T00:00:00Z`).toLocaleDateString('en-US', { month: 'short', year: 'numeric', timeZone: 'UTC' })
  : 'Beyond horizon'
const finite = value => typeof value === 'number' && Number.isFinite(value) && value >= 0
const MAX_QUANTITY = 1e12
const MAX_SUPPLIER_DAYS = 3650
const MONTH_RANGE_REASON = 'Sales months must be from 1000-01 through 9998-12.'
const quantity = value => finite(value) && value <= MAX_QUANTITY
const validMonth = month => typeof month === 'string' && /^[1-9][0-9]{3}-(0[1-9]|1[0-2])$/.test(month) && month <= '9998-12'
const historyReason = months => !Array.isArray(months) || !months.length || months.some(m => !validMonth(m))
  ? MONTH_RANGE_REASON : months.some((m, i) => i && monthAfter(months[i - 1], 1) !== m)
    ? 'Monthly sales columns must be consecutive full months.' : null
const bounded = value => {
  if (!Number.isFinite(value) || Math.abs(value) > 1e18) throw Error('Calculation exceeds supported arithmetic range.')
  return value
}
const sum = values => bounded(values.reduce((a, b) => bounded(a + b), 0))
const heldItem = (item, reason = "Couldn't calculate: check this item's data.") => ({
  sku: typeof item?.sku === 'string' ? item.sku : 'Item', name: typeof item?.name === 'string' ? item.name : 'Item',
  category: typeof item?.category === 'string' ? item.category : '', held: true, reason,
})

export function calculate(items, months, asOf, horizon) {
  if (!Number.isInteger(horizon) || horizon < 1 || horizon > 12) {
    throw Error('Horizon must be a whole number from 1 to 12.')
  }
  return items.map(item => {
    try {
      const sales = item.monthly_sales
      const held = reason => heldItem(item, reason)
      if (item.hold_reason) return held(typeof item.hold_reason === 'string' ? item.hold_reason : 'Check item data.')
      if (['sku', 'name', 'unit'].some(k => typeof item[k] !== 'string' || !item[k].trim())) {
        return held('SKU, name and unit are required.')
      }
      if (!quantity(item.on_hand) || !Array.isArray(sales) || sales.length < 3 || sales.some(x => !quantity(x))) {
        return held('Stock and at least three months of non-negative sales no greater than 1000000000000 are required.')
      }
      if (item.supplier_days != null && (!finite(item.supplier_days) || item.supplier_days > MAX_SUPPLIER_DAYS)) return held('Supplier days must be from 0 to 3650 when supplied.')
      const invalidHistory = historyReason(months)
      if (invalidHistory) return held(invalidHistory)
      if (typeof asOf !== 'string' || !/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(asOf)) return held('As-of date must be a month end.')
      monthAfter(months.at(-1), horizon)
      if (months.length !== sales.length || months.at(-1) !== asOf.slice(0, 7)) return held('Monthly history does not match its month labels.')
      const [year, mo] = asOf.slice(0, 7).split('-').map(Number)
      if (new Date(Date.UTC(year, mo, 0)).toISOString().slice(0, 10) !== asOf) return held('As-of date must be a month end.')
      const receipts = item.receipts ?? {}
      if (!receipts || Array.isArray(receipts) || typeof receipts !== 'object' || Object.values(receipts).some(x => !quantity(x))) {
        return held('Receipts must be an object of non-negative quantities no greater than 1000000000000.')
      }
      const stock = Math.floor(item.on_hand)
      const demand = Math.ceil(sum(sales.slice(-3)) / 3)
      let balance = stock, runout = null, runoutDay = null
      const projection = Array.from({ length: horizon }, (_, i) => {
        const month = monthAfter(asOf.slice(0, 7), i + 1)
        const receipt = receipts[month] ?? 0
        const opening = balance
        balance = bounded(balance - demand + receipt)
        if (balance <= 0 && runout === null) {
          runout = month
          const [y, m] = month.split('-').map(Number)
          const days = new Date(Date.UTC(y, m, 0)).getUTCDate()
          const elapsed = demand ? Math.max(0, (opening + receipt) / demand * days) : 0
          runoutDay = new Date(Date.UTC(y, m - 1, Math.max(1, Math.min(days, Math.ceil(elapsed)))))
        }
        return { month, demand, receipts: receipt, stock: balance }
      })
      const check = sales.length >= 7 ? sales.slice(-4).map((actual, j) => {
        const index = sales.length - 4 + j
        const window = sales.slice(index - 3, index)
        const mean = window.every(v => v === window[0]) ? window[0] : sum(window) / 3
        return { month: months[index], forecast: mean, actual }
      }) : []
      const total = sum(check.map(x => x.actual))
      const rawError = total ? bounded(sum(check.map(x => Math.abs(x.forecast - x.actual))) / total * 100) : null
      const error = rawError === null ? null : Math.floor(rawError + 0.5) || rawError
      const grade = !check.length ? 'Not enough history to check' : total === 0 ? 'No recent sales to check'
        : error <= 15 ? 'Usable for planning' : error <= 30 ? 'Use with care' : 'Too far off to plan on'
      const orderBy = runoutDay && item.supplier_days > 0
        ? new Date(runoutDay.getTime() - Math.ceil(item.supplier_days) * 86400000).toISOString().slice(0, 10) : null
      // Exercise history/stat arithmetic here so one unsafe item cannot crash rendering.
      historyStats(months, sales)
      inventoryHistory(item, months)
      return { ...item, receipts, stock, monthly_demand: demand, runout_month: runout,
        runout_day: runoutDay?.toISOString().slice(0, 10) ?? null, order_by: orderBy,
        projection, check, error_percent: error, grade, held: false }
    } catch { return heldItem(item) }
  })
}

class CsvError extends Error {}

export function parseCsv(text) {
  if (new TextEncoder().encode(text).length > 2 * 1024 * 1024) throw new CsvError('CSV must be no larger than 2 MiB.')
  text = text.replace(/^\uFEFF/, '')
  const rows = []
  let row = [], cell = '', quoted = false, closed = false
  const pushRow = () => {
    row.push(cell)
    if (row.length > 1 || row[0] !== '') rows.push(row)
    row = []; cell = ''; closed = false
  }
  for (let i = 0; i < text.length; i++) {
    const c = text[i]
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') { cell += '"'; i++ }
      else if (c === '"') { quoted = false; closed = true }
      else cell += c
    } else if (c === '"' && !cell && !closed) quoted = true
    else if (c === ',') { row.push(cell); cell = ''; closed = false }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++
      pushRow()
    } else {
      if (closed) throw new CsvError('Could not read the local CSV file.')
      cell += c
    }
  }
  if (quoted) throw new CsvError('Could not read the local CSV file.')
  pushRow()
  const headers = rows.shift() || []
  const fixed = ['sku', 'name', 'unit', 'on_hand', 'supplier_days']
  if (fixed.some((x, i) => headers[i] !== x)) throw new CsvError('CSV columns must begin: sku,name,unit,on_hand,supplier_days.')
  const extra = headers.slice(5)
  const months = extra.filter(h => h !== 'category' && !h.startsWith('rcv:'))
  if (months.length < 3 || months.some(m => !/^[1-9][0-9]{3}-(0[1-9]|1[0-2])$/.test(m))) {
    throw new CsvError('Add at least three YYYY-MM monthly sales columns after supplier_days.')
  }
  if (months.some(m => !validMonth(m))) throw new CsvError(MONTH_RANGE_REASON)
  if (new Set(months).size !== months.length || months.some((m, i) => i && m <= months[i - 1])) {
    throw new CsvError('Monthly sales columns must be unique and in chronological order.')
  }
  if (months.some((m, i) => i && monthAfter(months[i - 1], 1) !== m)) throw new CsvError('Monthly sales columns must be consecutive full months.')
  const receiptColumns = extra.filter(h => h.startsWith('rcv:'))
  if (extra.filter(h => h === 'category').length > 1) throw new CsvError('Category column must be unique.')
  if (receiptColumns.length && (new Set(receiptColumns).size !== receiptColumns.length
      || receiptColumns.some(h => !/^[1-9][0-9]{3}-(0[1-9]|1[0-2])$/.test(h.slice(4)))
      || receiptColumns.length !== months.length || months.some(m => !receiptColumns.includes(`rcv:${m}`)))) {
    throw new CsvError('Receipt columns must be unique valid rcv:YYYY-MM columns covering every sales month exactly.')
  }
  if (rows.length > 10000) throw new CsvError('CSV contains more than 10000 rows.')
  const numeric = (raw, rownum, column, nullable = false) => {
    if (raw === '' && nullable) return null
    if (!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/.test(raw.trim())) {
      throw new CsvError(`Row ${rownum}: ${column} must be a number.`)
    }
    if (!finite(Number(raw))) throw new CsvError(`Row ${rownum}: ${column} must be a non-negative number.`)
    const limit = column === 'supplier_days' ? MAX_SUPPLIER_DAYS : MAX_QUANTITY
    if (Number(raw) > limit) throw new CsvError(`Row ${rownum}: ${column} must be no greater than ${limit}.`)
    return Number(raw)
  }
  const seen = new Set()
  const items = rows.map((values, i) => {
    const rownum = i + 2
    if (values.length !== headers.length) throw new CsvError(`Row ${rownum}: column count does not match the header.`)
    if (values.slice(0, 3).some(x => !x.trim())) throw new CsvError(`Row ${rownum}: sku, name, and unit are required.`)
    const sku = values[0].trim()
    if (seen.has(sku)) throw new CsvError(`Row ${rownum}: duplicate sku.`)
    seen.add(sku)
    return { sku, name: values[1].trim(), unit: values[2].trim(), on_hand: numeric(values[3], rownum, 'on_hand'),
      supplier_days: numeric(values[4], rownum, 'supplier_days', true),
      monthly_sales: months.map(m => numeric(values[headers.indexOf(m)], rownum, m)), receipts: {},
      ...(extra.includes('category') ? { category: values[headers.indexOf('category')].trim() } : {}),
      ...(receiptColumns.length ? { historical_receipts: Object.fromEntries(receiptColumns.map(h => [h.slice(4), numeric(values[headers.indexOf(h)], rownum, h)])) } : {}) }
  })
  if (!items.length) throw new CsvError('CSV has no item rows.')
  const [y, m] = months.at(-1).split('-').map(Number)
  return { as_of: new Date(Date.UTC(y, m, 0)).toISOString().slice(0, 10), months, items }
}

// SDK tones: StatusDot uses bad/warn/muted; Badge uses destructive/warn/success.
export function urgencyTone(runoutMonth, asOf) {
  if (!runoutMonth) return 'muted'
  const [year, month] = runoutMonth.split('-').map(Number)
  const [asOfYear, asOfMonth] = asOf.slice(0, 7).split('-').map(Number)
  const monthsAway = (year - asOfYear) * 12 + month - asOfMonth
  return monthsAway <= 1 ? 'bad' : monthsAway <= 3 ? 'warn' : 'muted'
}

export const gradeVariant = grade => ({
  'Usable for planning': 'success',
  'Use with care': 'warn',
  'Too far off to plan on': 'destructive',
}[grade] || 'muted')

export function inventoryHistory(item, months) {
  const receipts = item.historical_receipts
  const absent = { rows: [], warning: 'Add delivery history to see past inventory.' }
  if (historyReason(months) || !quantity(item.on_hand) || !Array.isArray(item.monthly_sales) || item.monthly_sales.some(v => !quantity(v)) || !receipts || typeof receipts !== 'object' || Array.isArray(receipts)
      || Object.keys(receipts).length !== months.length || item.monthly_sales.length !== months.length
      || months.some(m => !Object.hasOwn(receipts, m) || !quantity(receipts[m]))) return absent
  const balances = Array(months.length).fill(item.on_hand)
  for (let i = months.length - 2; i >= 0; i--) balances[i] = bounded(balances[i + 1] + item.monthly_sales[i + 1] - receipts[months[i + 1]])
  const negative = balances.findLastIndex(value => value < 0)
  return { rows: months.map((month, i) => ({ month, raw_stock: balances[i], stock: Math.max(0, balances[i]), delivered: receipts[month] })),
    warning: negative < 0 ? null : `Supply history looks incomplete before ${label(months[negative + 1])}` }
}

export function stockPath(item) {
  const points = [{ month: 0, stock: item.stock }]
  if (item.stock === 0) return { points, crossing: { month: 0, label: item.projection[0]?.month } }
  for (const [index, row] of item.projection.entries()) {
    const previous = points.at(-1)
    if (row.stock <= 0) {
      const month = index + previous.stock / (previous.stock - row.stock)
      points.push({ month, stock: 0 })
      return { points, crossing: { month, label: row.month } }
    }
    points.push({ month: index + 1, stock: row.stock })
  }
  return { points, crossing: null }
}

// Summarize every supplied month. A trend needs two complete three-month
// windows; a zero prior window has direction but no finite percentage base.
export function historyStats(months, sales) {
  if (sales.some(v => !quantity(v))) throw Error('Sales quantities exceed the supported range.')
  const count = sales.length
  const average = count ? sum(sales) / count : 0
  const bestValue = count ? sales.reduce((best, sold) => Math.max(best, sold), -Infinity) : 0
  const slowestValue = count ? sales.reduce((slowest, sold) => Math.min(slowest, sold), Infinity) : 0
  const newestTie = value => {
    const index = sales.lastIndexOf(value)
    return { month: months[index], sold: value }
  }
  let trend = null
  if (count >= 6) {
    const previous = sum(sales.slice(-6, -3))
    const recent = sum(sales.slice(-3))
    const direction = recent > previous ? 'up' : recent < previous ? 'down' : 'flat'
    trend = { direction, percent: previous === 0 ? (recent === 0 ? 0 : null) : bounded(Math.abs(recent - previous) / previous * 100) }
  }
  return { count, average, best: count ? newestTie(bestValue) : null,
    slowest: count ? newestTie(slowestValue) : null, trend }
}

const format = value => value !== 0 && Math.abs(value) < 0.01 ? (value < 0 ? '−<0.01' : '<0.01')
  : value.toLocaleString('en-US', { maximumFractionDigits: Math.abs(value) < 10 ? 2 : 1 })
// Round a raw step up to 1, 2, 2.5 or 5 x 10^n so ticks are whole, readable numbers.
export const niceStep = raw => { const p = 10 ** Math.floor(Math.log10(raw)); return [1, 2, 2.5, 5, 10].map(m => m * p).find(v => v >= raw) }
// Below zero the shelf is empty: show the unmet demand instead of negative stock.
export const stockCell = stock => stock > 0 ? format(stock) : stock === 0 ? 'Out' : `Out (short ${format(-stock)})`
export const tickLabel = value => Math.abs(value) >= 10000 ? `${format(value / 1000)}k` : format(value)

// transcript-directives.ts:64,197: 2048-char body, 4800-char paragraph.
export const CARD_MAX_LINE = 1900
const CARD_PREFIX = '::stock-runway{data="'
const CARD_SUFFIX = '"}'
const GRADES = ['Usable for planning', 'Use with care', 'Too far off to plan on',
  'Not enough history to check', 'No recent sales to check', 'Check item data']
const keysAre = (value, keys) => value !== null && typeof value === 'object' && !Array.isArray(value)
  && Object.keys(value).length === keys.length && keys.every(key => Object.hasOwn(value, key))
const wellFormed = value => typeof value !== 'string' || ![...value].some(char => {
  const point = char.codePointAt(0)
  return point >= 0xD800 && point <= 0xDFFF
})
const cardUnicode = data => wellFormed(data?.disclosure) && (!Array.isArray(data?.rows)
  || data.rows.every(row => wellFormed(row?.sku) && wellFormed(row?.name)))
const boundedText = (value, max) => typeof value === 'string' && value.trim().length > 0 && [...value].length <= max
const isMonth = value => typeof value === 'string' && /^[1-9][0-9]{3}-(0[1-9]|1[0-2])$/.test(value)
export const sortRows = rows => [...rows].sort((a, b) => Number(a.held) - Number(b.held)
  || (a.runout || '9999-99').localeCompare(b.runout || '9999-99')
  || (a.runout_day || '9999-12-31').localeCompare(b.runout_day || '9999-12-31'))

export function validCard(data) {
  if (!keysAre(data, ['as_of', 'horizon', 'disclosure', 'rows', 'more']) || !cardUnicode(data)
    || !Number.isSafeInteger(data.more) || data.more < 0
    || typeof data.as_of !== 'string' || !/^[1-9][0-9]{3}-(0[1-9]|1[0-2])-[0-3][0-9]$/.test(data.as_of)
    || !Number.isInteger(data.horizon) || data.horizon < 1 || data.horizon > 12
    || !boundedText(data.disclosure, 512) || !Array.isArray(data.rows) || data.rows.length > 50) return false
  const [year, month] = data.as_of.slice(0, 7).split('-').map(Number)
  if (new Date(Date.UTC(year, month, 0)).toISOString().slice(0, 10) !== data.as_of) return false
  const seen = new Set()
  return data.rows.every(row => {
    if (!keysAre(row, ['sku', 'name', 'runout', 'grade', 'stock', 'monthly', 'held'])
      || !boundedText(row.sku, 120) || !boundedText(row.name, 240) || seen.has(row.sku)
      || typeof row.held !== 'boolean' || !GRADES.includes(row.grade)) return false
    seen.add(row.sku)
    if (row.held) return row.runout === null && row.stock === null && row.monthly === null && row.grade === 'Check item data'
    return row.grade !== 'Check item data' && finite(row.stock) && finite(row.monthly)
      && (row.runout === null || isMonth(row.runout) && row.runout > data.as_of.slice(0, 7)
        && row.runout <= monthAfter(data.as_of.slice(0, 7), data.horizon))
  })
}

// UTF-8, unpadded, canonical base64url. Never evaluate untrusted transcript text.
const skipBlankIds = data => {
  if (!Array.isArray(data?.rows) || !Number.isSafeInteger(data.more) || data.more < 0) return data
  const rows = data.rows.filter(row => typeof row?.sku !== 'string' || row.sku.trim())
  return { ...data, rows, more: data.more + data.rows.length - rows.length }
}
export function encodeCard(data) {
  if (!cardUnicode(data)) return null
  data = skipBlankIds(data)
  if (!validCard(data)) throw Error('Invalid stock card.')
  const rows = sortRows(data.rows)
  while (true) {
    const dto = { ...data, rows, more: data.more + data.rows.length - rows.length }
    const bytes = new TextEncoder().encode(JSON.stringify(dto))
    const encoded = btoa(Array.from(bytes, byte => String.fromCharCode(byte)).join(''))
      .replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '')
    const line = `${CARD_PREFIX}${encoded}${CARD_SUFFIX}`
    if (line.length <= CARD_MAX_LINE) return line
    if (!rows.length) return null
    rows.pop()
  }
}
export function decodeCard(attrs) {
  try {
    if (!keysAre(attrs, ['data']) || typeof attrs.data !== 'string'
      || attrs.data.length + CARD_PREFIX.length + CARD_SUFFIX.length > CARD_MAX_LINE
      || !/^[A-Za-z0-9_-]+$/.test(attrs.data) || attrs.data.length % 4 === 1) return null
    const raw = atob(attrs.data.replaceAll('-', '+').replaceAll('_', '/') + '='.repeat((4 - attrs.data.length % 4) % 4))
    const text = new TextDecoder('utf-8', { fatal: true }).decode(Uint8Array.from(raw, char => char.charCodeAt(0)))
    const parsed = JSON.parse(text)
    if (!cardUnicode(parsed)) return null
    const data = skipBlankIds(parsed)
    if (!validCard(data)) return null
    // Reject noncanonical base64 trailing bits, but allow JSON whitespace from other encoders.
    const canonical = btoa(raw).replaceAll('+', '-').replaceAll('/', '_').replace(/=+$/, '')
    return canonical === attrs.data ? data : null
  } catch { return null }
}

export function evaluateDataset(data, horizon) {
  if (!data || !Array.isArray(data.items) || !data.items.length || historyReason(data.months)
      || typeof data.as_of !== 'string') throw Error('Could not calculate this dataset. Choose another file or go back to sample data.')
  const [year, month] = data.months.at(-1).split('-').map(Number)
  if (new Date(Date.UTC(year, month, 0)).toISOString().slice(0, 10) !== data.as_of) {
    throw Error('Could not calculate this dataset. Choose another file or go back to sample data.')
  }
  return calculate(data.items, data.months, data.as_of, horizon)
}

export function quickData(ctx) {
  try {
    const source = ctx.storage.get('source', 'sample')
    const data = source === 'csv' ? ctx.storage.get('csv_data', null) : SAMPLE
    if (!data) return null
    const horizon = savedHorizon(ctx)
    const results = evaluateDataset(data, horizon)
      .sort((a, b) => Number(a.held) - Number(b.held)
        || (a.runout_day || '9999-12-31').localeCompare(b.runout_day || '9999-12-31'))
    const visible = results.filter(item => typeof item.sku === 'string' && item.sku.trim())
    return { as_of: data.as_of, horizon, more: results.length - visible.length,
      disclosure: `${source === 'csv' ? 'Local CSV' : 'Sample data'} · Estimate from the last 3 months of sales. Assumes nothing is on order.`,
      rows: visible.map(item => ({ sku: item.sku, name: item.name, runout: item.held ? null : item.runout_month,
        grade: item.held ? 'Check item data' : item.grade, stock: item.held ? null : item.on_hand,
        monthly: item.held ? null : item.monthly_demand, held: item.held })) }
  } catch { return { error: true } }
}

export const DEFAULT_ORDER_SETTINGS = Object.freeze({ default_delivery_days: 14, months_of_cover: 2,
  overstock_months: 6, urgent_days: 7, running_low_days: 30, product_overrides: {} })
const safeSettingNumber = (value, min, max, integer = false) => typeof value === 'number' && Number.isFinite(value)
  && value >= min && value <= max && (!integer || Number.isInteger(value))
const normalizeOrderSettings = value => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return { ...DEFAULT_ORDER_SETTINGS, product_overrides: {} }
  const fallback = DEFAULT_ORDER_SETTINGS
  const fields = {
    default_delivery_days: value.default_delivery_days === null ? null : safeSettingNumber(value.default_delivery_days, 1, MAX_SUPPLIER_DAYS, true) ? value.default_delivery_days : fallback.default_delivery_days,
    months_of_cover: safeSettingNumber(value.months_of_cover, 0, 36) ? value.months_of_cover : fallback.months_of_cover,
    overstock_months: safeSettingNumber(value.overstock_months, 0.1, 120) ? value.overstock_months : fallback.overstock_months,
    urgent_days: safeSettingNumber(value.urgent_days, 0, 3650, true) ? value.urgent_days : fallback.urgent_days,
    running_low_days: safeSettingNumber(value.running_low_days, 0, 3650, true) ? value.running_low_days : fallback.running_low_days,
  }
  const overrides = {}
  if (value.product_overrides && typeof value.product_overrides === 'object' && !Array.isArray(value.product_overrides)) {
    for (const [sku, entry] of Object.entries(value.product_overrides)) {
      if (!entry || typeof entry !== 'object' || Array.isArray(entry)) continue
      const normalized = {}
      for (const key of ['minimum_order', 'pack_size']) {
        if (entry[key] == null || entry[key] === '') continue
        if (safeSettingNumber(entry[key], Number.MIN_VALUE, MAX_QUANTITY)) normalized[key] = entry[key]
      }
      if (Object.keys(normalized).length) overrides[sku] = normalized
    }
  }
  return { ...fields, product_overrides: overrides }
}
export { normalizeOrderSettings }

const dateOrdinal = date => {
  if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return null
  const parsed = new Date(`${date}T00:00:00Z`)
  return Number.isFinite(parsed.getTime()) && parsed.toISOString().slice(0, 10) === date ? Math.floor(parsed.getTime() / 86400000) : null
}
const ordinalDate = ordinal => {
  if (!Number.isSafeInteger(ordinal)) return null
  const date = new Date(ordinal * 86400000)
  return Number.isFinite(date.getTime()) && date.getUTCFullYear() >= 1000 && date.getUTCFullYear() <= 9999
    ? date.toISOString().slice(0, 10) : null
}
const monthEndOrdinal = month => {
  if (typeof month !== 'string' || !/^\d{4}-(0[1-9]|1[0-2])$/.test(month)) return null
  const [year, monthNum] = month.split('-').map(Number)
  if (year < 1000 || year > 9999) return null
  return dateOrdinal(new Date(Date.UTC(year, monthNum, 0)).toISOString().slice(0, 10))
}
const formatDate = date => date === 'now' ? 'now' : dateOrdinal(date) === null ? 'date unavailable'
  : new Date(`${date}T00:00:00Z`).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric', timeZone: 'UTC' })

// Decimal rationals avoid binary rounding noise when ordering fractional packs.
const decimalRatio = value => {
  const [coefficient, exponent = '0'] = String(value).split('e')
  const places = (coefficient.split('.')[1] || '').length - Number(exponent)
  const digits = BigInt(coefficient.replace('.', ''))
  return places < 0 ? [digits * 10n ** BigInt(-places), 1n] : [digits, 10n ** BigInt(places)]
}
const subtractRatio = ([a, b], [c, d]) => [a * d - c * b, b * d]
const compareRatio = ([a, b], [c, d]) => a * d - c * b
const MIN_ORDER_INCREMENT = 0.000001
const validOrderIncrement = value => {
  if (!safeSettingNumber(value, MIN_ORDER_INCREMENT, MAX_QUANTITY)) return false
  const [numerator, denominator] = decimalRatio(value)
  return numerator * 1000000n % denominator === 0n
}
const roundedOrderQuantity = (forecast, onHand, receipts, override) => {
  let need = subtractRatio(forecast, decimalRatio(onHand))
  for (const amount of receipts) need = subtractRatio(need, decimalRatio(amount))
  if (need[0] <= 0n) return 0
  const minimum = decimalRatio(override.minimum_order || 0)
  if (compareRatio(need, minimum) < 0n) need = minimum
  const [packN, packD] = decimalRatio(override.pack_size || 1)
  const numerator = need[0] * packD, denominator = need[1] * packN
  const packs = (numerator + denominator - 1n) / denominator
  const total = packs * packN
  // packD is a power of ten. Convert via decimal text, not floating multiplication.
  const places = String(packD).length - 1
  const digits = String(total).padStart(places + 1, '0')
  const quantity = Number(places ? `${digits.slice(0, -places)}.${digits.slice(-places)}` : digits)
  if (!Number.isFinite(quantity) || quantity > Math.min(1e18, Number.MAX_SAFE_INTEGER)
      || compareRatio(decimalRatio(quantity), [total, packD]) !== 0n) return null
  return quantity
}

// A full calendar month consumes one monthly forecast. A partial month consumes
// elapsed days / days in that month, from the snapshot month-end (exclusive).
// Rationals keep the final minimum/pack ceiling exact, even at source-cell limits.
const calendarDemand = (demand, asOf, endpoint) => {
  if (endpoint <= dateOrdinal(asOf)) return [0n, 1n]
  const end = new Date(endpoint * 86400000)
  const [year, month] = asOf.slice(0, 7).split('-').map(Number)
  const whole = end.getUTCFullYear() * 12 + end.getUTCMonth() - (year * 12 + month)
  const days = new Date(Date.UTC(end.getUTCFullYear(), end.getUTCMonth() + 1, 0)).getUTCDate()
  const [n, d] = decimalRatio(demand)
  return [n * BigInt(whole * days + end.getUTCDate()), d * BigInt(days)]
}
const ratioValue = ([n, d]) => Number(n) / Number(d)

// Like calculate, floor snapshot stock and add receipts at START of their month
// before consuming calendar demand. Retain the first zero day after recovery.
// After the last receipt, jump to the crossing month beyond the displayed horizon.
const guidanceCalendar = (item, asOf, todayOrdinal) => {
  const demand = item.monthly_demand
  let balance = Math.floor(item.on_hand), runout = null
  const [year, month] = asOf.slice(0, 7).split('-').map(Number)
  let index = year * 12 + month
  const lastIndex = 9999 * 12 + 11
  const events = Object.keys(item.receipts || {}).filter(m => m > asOf.slice(0, 7))
  const lastReceipt = events.length ? Math.max(...events.map(m => { const [y, n] = m.split('-').map(Number); return y * 12 + n - 1 })) : index - 1
  const crossingDate = (i, opening) => {
    const y = Math.floor(i / 12), m = i % 12
    const days = new Date(Date.UTC(y, m + 1, 0)).getUTCDate()
    const [n, d] = decimalRatio(Math.max(0, opening)), [dn, dd] = decimalRatio(demand)
    const numerator = n * dd * BigInt(days), denominator = d * dn
    const elapsed = demand ? Number((numerator + denominator - 1n) / denominator) : 0
    return new Date(Date.UTC(y, m, Math.max(1, Math.min(days, elapsed)))).toISOString().slice(0, 10)
  }
  while (index <= lastReceipt && index <= lastIndex) {
    const m = `${Math.floor(index / 12)}-${String(index % 12 + 1).padStart(2, '0')}`
    const receipt = item.receipts[m] || 0
    if (!runout && demand > 0 && balance - demand + receipt <= 0) runout = crossingDate(index, balance + receipt)
    balance = bounded(balance - demand + receipt)
    index++
  }
  if (!runout && demand > 0) {
    const steps = Math.max(1, Math.ceil(balance / demand))
    const crossingIndex = index + steps - 1
    if (!Number.isSafeInteger(crossingIndex) || crossingIndex > lastIndex) return { invalid: true }
    runout = crossingDate(crossingIndex, balance - (steps - 1) * demand)
  }
  // Today and quantity use the same start-of-month receipt event as run-out.
  // A later delivery can restore today's balance without erasing the first gap.
  let available = Math.floor(item.on_hand), delivery = null, deliveryQuantity = null
  for (const m of events.sort()) {
    const due = dateOrdinal(`${m}-01`), amount = item.receipts[m]
    if (due <= todayOrdinal) available = bounded(available + amount)
    if (!delivery && runout && due > dateOrdinal(runout) && amount > 0) {
      delivery = ordinalDate(due)
      deliveryQuantity = amount
    }
  }
  const todayBalance = subtractRatio(decimalRatio(available), calendarDemand(demand, asOf, todayOrdinal))
  const outOfStock = todayBalance[0] <= 0n
  const gap = delivery || outOfStock ? runout || ordinalDate(todayOrdinal) : null
  return { runout, gap, delivery, deliveryQuantity, outOfStock, balanceToday: ratioValue(todayBalance) }
}

export function orderGuidance(item, today, rawSettings = DEFAULT_ORDER_SETTINGS, asOf = item?.as_of) {
  const settings = normalizeOrderSettings(rawSettings)
  const todayOrdinal = dateOrdinal(today), snapshot = dateOrdinal(asOf)
  const demand = item?.monthly_demand
  if (todayOrdinal === null || snapshot === null || monthEndOrdinal(asOf?.slice(0, 7)) !== snapshot
      || item?.held || !safeSettingNumber(item?.on_hand, 0, MAX_QUANTITY)
      || !safeSettingNumber(demand, 0, MAX_QUANTITY)) return { status: 'needs-data', reason: item?.reason || 'Needs a valid stock date, stock and forecast.' }
  const override = settings.product_overrides[item.sku] || {}
  // Invalid persisted pack values must not silently become whole-unit orders.
  const rawOverride = rawSettings?.product_overrides?.[item.sku] || {}
  for (const [key, title] of [['pack_size', 'Pack size'], ['minimum_order', 'Minimum order']]) {
    if (rawOverride[key] != null && rawOverride[key] !== '' && !(key === 'minimum_order' && rawOverride[key] === 0) && !validOrderIncrement(rawOverride[key]))
      return { status: 'needs-data', reason: `${title} must be from 0.000001 to 1000000000000, with at most six decimal places.` }
  }
  const sourceLead = item.supplier_days == null ? settings.default_delivery_days : item.supplier_days
  if (sourceLead === null || !safeSettingNumber(sourceLead, 0, MAX_SUPPLIER_DAYS)) return { status: 'needs-data', reason: 'No delivery time — set one in Advanced' }
  const lead = Math.ceil(sourceLead), coverDays = Math.ceil(settings.months_of_cover * 30)
  for (const [month, amount] of Object.entries(item.receipts || {})) {
    if (monthEndOrdinal(month) === null || !safeSettingNumber(amount, 0, MAX_QUANTITY))
      return { status: 'needs-data', reason: 'Confirmed delivery data needs checking.' }
  }
  let calendar
  try { calendar = guidanceCalendar(item, asOf, todayOrdinal) }
  catch { return { status: 'needs-data', reason: 'The forecast exceeds the supported arithmetic range.' } }
  if (calendar.invalid) return { status: 'needs-data', reason: 'The estimated run-out date exceeds the supported calendar.' }
  const dueOrdinal = calendar.runout ? dateOrdinal(calendar.runout) - lead : null
  const dueDate = dueOrdinal === null ? null : ordinalDate(dueOrdinal)
  if (dueOrdinal !== null && dueDate === null) return { status: 'needs-data', reason: 'The order date exceeds the supported calendar.' }
  const due = dueOrdinal !== null && dueOrdinal <= todayOrdinal ? 'now' : dueDate
  const orderDate = Math.max(todayOrdinal, dueOrdinal ?? todayOrdinal)
  const end = orderDate + lead + coverDays
  if (ordinalDate(end) === null) return { status: 'needs-data', reason: 'The delivery and cover dates exceed the supported calendar.' }
  let incoming = 0
  const includedReceipts = []
  for (const [month, amount] of Object.entries(item.receipts || {})) {
    const receiptDate = dateOrdinal(`${month}-01`)
    if (receiptDate > snapshot && receiptDate <= end) { incoming += amount; includedReceipts.push(amount) }
  }
  if (!Number.isFinite(incoming) || incoming > 1e18) return { status: 'needs-data', reason: 'Confirmed delivery total is outside the supported range.' }
  const quantity = roundedOrderQuantity(calendarDemand(demand, asOf, end), item.on_hand, includedReceipts, override)
  if (quantity === null) return { status: 'needs-data', reason: 'The rounded quantity exceeds safe decimal precision (maximum 9007199254740991 units).' }
  const outOfStock = calendar.outOfStock
  const status = quantity > 0 ? 'order' : calendar.gap || outOfStock ? 'supply-gap'
    : demand === 0 && item.on_hand > 0 ? 'overstocked' : 'healthy'
  return { status, reason: '', quantity, lead_days: lead, used_default_lead: item.supplier_days == null,
    incoming, runout_date: calendar.runout, order_by: due, out_of_stock: outOfStock, stock_date: asOf,
    supply_gap: Boolean(calendar.gap), gap_date: calendar.gap, delivery_date: calendar.delivery, delivery_quantity: calendar.deliveryQuantity,
    overstock_months: demand > 0 ? item.on_hand / demand : item.on_hand > 0 ? Infinity : 0,
    monthly_demand: demand, projected_balance_today: calendar.balanceToday,
    order_date: ordinalDate(orderDate), endpoint: ordinalDate(end) }
}

export function orderBucket(item, today, rawSettings = DEFAULT_ORDER_SETTINGS, asOf = item?.as_of) {
  const settings = normalizeOrderSettings(rawSettings)
  const guidance = orderGuidance(item, today, rawSettings, asOf)
  if (guidance.status === 'needs-data') return 'needs-data'
  const due = dateOrdinal(guidance.order_by)
  if (guidance.out_of_stock || guidance.order_by === 'now' || due !== null && due <= dateOrdinal(today) + settings.urgent_days) return 'order'
  if (due !== null && due <= dateOrdinal(today) + settings.running_low_days) return 'running-low'
  if (item.on_hand > 0 && item.monthly_sales?.length >= 3 && item.monthly_sales.slice(-3).every(value => value === 0)) return 'no-sales'
  if (guidance.overstock_months > settings.overstock_months) return 'overstocked'
  return 'healthy'
}
const orderAmount = value => value.toLocaleString('en-GB', { maximumFractionDigits: 6 })
const orderSentence = (item, guidance) => `Order ${orderAmount(guidance.quantity)} ${item.unit} ${guidance.order_by === 'now' ? 'now' : `by ${formatDate(guidance.order_by)}`}`
const shortageSentence = (item, guidance) => guidance.delivery_date
  ? `Short from ${formatDate(guidance.gap_date)} until the ${label(guidance.delivery_date.slice(0, 7)).split(' ')[0]} delivery of ${orderAmount(guidance.delivery_quantity)} ${item.unit}.` : null
const gapSentence = guidance => guidance.delivery_date
  ? `${guidance.out_of_stock ? 'Out of stock — ' : ''}No extra order needed for the selected cover period.`
  : guidance.monthly_demand === 0 ? 'Out of stock — no recent sales; no order quantity suggested.'
    : 'Out of stock — no extra order needed for the selected cover period.'

const noOrderSentence = (item, guidance) => guidance.supply_gap || guidance.out_of_stock ? gapSentence(guidance)
  : guidance.monthly_demand === 0 ? 'No order needed — stock on hand with no recent sales'
    : guidance.incoming > 0 ? `No order needed — ${format(guidance.incoming)} ${item.unit} in confirmed deliveries cover the order period`
      : `No order needed — enough stock until ${formatDate(guidance.runout_date)}`

const pageStyle = { minWidth: 0, padding: 16, boxSizing: 'border-box', color: 'var(--ui-text-primary)', fontFamily: 'inherit', overflowWrap: 'anywhere' }
// Disclosure headers: at least 40px tall so they're easy to click/tap (controls audit 2026-11-11).
const summaryHit = { cursor: 'pointer', fontWeight: 600, minHeight: 40, padding: '10px 0', boxSizing: 'border-box' }
const muted = { color: 'var(--ui-text-secondary)' }
const sectionStyle = { minWidth: 0, border: '1px solid var(--ui-stroke-secondary)', borderRadius: 12, padding: 16, marginTop: 24, background: 'color-mix(in srgb, var(--ui-bg-secondary) 22%, transparent)' }
const cellStyle = { textAlign: 'right', fontVariantNumeric: 'tabular-nums', padding: '8px 8px', borderBottom: '1px solid var(--ui-stroke-secondary)', whiteSpace: 'nowrap' }

