  healthy: 'm5 12 4 4L19 6', overstocked: 'M12 20V4m-6 6 6-6 6 6',
  'no-sales': 'M5 12h14', 'needs-data': 'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01',
  truck: 'M2 5h12v12H2Zm12 4h4l4 4v4h-8M7 19a2 2 0 1 0 0-4 2 2 0 0 0 0 4m12 0a2 2 0 1 0 0-4 2 2 0 0 0 0 4',
  calendar: 'M4 5h16v16H4ZM4 10h16M8 3v4m8-4v4',
  box: 'm3 7 9-4 9 4v10l-9 4-9-4Zm0 0 9 4 9-4M12 11v10M7 5l10 4',
  gear: 'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1ZM15 12a3 3 0 1 0-6 0 3 3 0 0 0 6 0',
  chevron: 'm6 9 6 6 6-6',
